// Draws the picture link previews show (Facebook, X, Bluesky, LinkedIn,
// messaging apps) and writes it into a generated module the Worker serves.
//
//   node scripts/build-share-card.js    writes src/worker/share-card.generated.ts
//
// The card is the shop's name and tagline beside the Broadcast's host, drawn
// from the host's own art (src/worker/host-art.ts) so the two never drift. It
// is a JPEG because the big platforms ignore SVG previews.
//
// The generated file is committed, so deploys and tests need no build step.
// It is NOT checked in CI: the lettering uses the machine's own serif and
// monospace fonts, so a re-run elsewhere gives a slightly different image.
// Re-run it only when the card's design or the host's drawing changes.
//
// PW_CHROME_CHANNEL=chrome uses an installed Chrome, as playwright.config.ts does.

import { Buffer } from "node:buffer";
import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { chromium } from "@playwright/test";
import { build } from "esbuild";

const WIDTH = 1200;
const HEIGHT = 630;
const root = new URL("../", import.meta.url);
const outFile = new URL("src/worker/share-card.generated.ts", root);

/** The host's drawing as plain SVG markup, without its title and description. */
async function hostMarkup() {
  const result = await build({
    entryPoints: [fileURLToPath(new URL("src/worker/host-art.ts", root))],
    bundle: true,
    format: "esm",
    platform: "node",
    write: false,
    logLevel: "silent",
  });
  const source = result.outputFiles[0].text;
  const { hostArt } = await import(
    `data:text/javascript;base64,${Buffer.from(source).toString("base64")}`
  );
  return String(hostArt().value)
    .trim()
    .replace(/^<svg[^>]*>/s, "")
    .replace(/<\/svg>$/, "")
    .replace(/<title.*?<\/title>|<desc.*?<\/desc>/gs, "");
}

function cardSvg(host) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${HEIGHT}" viewBox="0 0 ${WIDTH} ${HEIGHT}">
  <defs>
    <radialGradient id="spot" cx="62%" cy="45%" r="70%">
      <stop offset="0" stop-color="#3a4558"/>
      <stop offset="1" stop-color="#151a23"/>
    </radialGradient>
    <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
      <path d="M40 0H0V40" fill="none" stroke="#ffffff" stroke-opacity="0.05" stroke-width="1"/>
    </pattern>
    <radialGradient id="glow" cx="50%" cy="50%" r="50%">
      <stop offset="0" stop-color="#9fe8c6" stop-opacity="0.5"/>
      <stop offset="1" stop-color="#9fe8c6" stop-opacity="0"/>
    </radialGradient>
  </defs>
  <rect width="${WIDTH}" height="${HEIGHT}" fill="url(#spot)"/>
  <rect width="${WIDTH}" height="${HEIGHT}" fill="url(#grid)"/>
  <ellipse cx="900" cy="330" rx="330" ry="300" fill="url(#glow)"/>
  <g transform="translate(700 40) scale(1.12)">${host}</g>
  <g font-family="Georgia, 'Times New Roman', serif" fill="#f4efe4">
    <text x="64" y="120" font-family="'Courier New', monospace" font-size="26" letter-spacing="6" fill="#9fe8c6">PURVEYORS OF RARE OBJECTS</text>
    <text x="64" y="250" font-size="104" font-weight="700">Allegedly</text>
    <text x="64" y="352" font-size="104" font-weight="700">&amp; Sons</text>
    <text x="64" y="428" font-size="34" fill="#d8d2c4">Rare objects with extraordinary,</text>
    <text x="64" y="472" font-size="34" fill="#d8d2c4">completely unverifiable histories.</text>
  </g>
  <g transform="translate(64 540) rotate(-2)">
    <rect width="590" height="52" rx="4" fill="none" stroke="#9fe8c6" stroke-width="3"/>
    <text x="295" y="34" text-anchor="middle" font-family="'Courier New', monospace" font-size="19" letter-spacing="2" fill="#9fe8c6">THE BUREAU OF IMPROBABLE ACQUISITIONS</text>
  </g>
</svg>`;
}

const channel = process.env["PW_CHROME_CHANNEL"];
const browser = await chromium.launch(channel === undefined ? {} : { channel });
try {
  const page = await browser.newPage({
    viewport: { width: WIDTH, height: HEIGHT },
    deviceScaleFactor: 1,
  });
  await page.setContent(`<body style="margin:0">${cardSvg(await hostMarkup())}</body>`);
  const jpeg = await page.screenshot({
    type: "jpeg",
    quality: 88,
    clip: { x: 0, y: 0, width: WIDTH, height: HEIGHT },
  });
  const file = `// Generated by scripts/build-share-card.js. Do not edit by hand.
// The link-preview card: ${String(WIDTH)}x${String(HEIGHT)} JPEG, base64.
export const SHARE_CARD_BASE64 =
  "${jpeg.toString("base64")}";
`;
  await writeFile(outFile, file);
  console.log(`Wrote ${fileURLToPath(outFile)} (${String(jpeg.length)} bytes of JPEG).`);
} finally {
  await browser.close();
}
